  manifesto text := $manifesto$[{"tabela":"candidatos","id":"1d083d19-96c3-4a41-9d75-6abffacc4a3a","candidato_id":"1d083d19-96c3-4a41-9d75-6abffacc4a3a","slug":"acm-neto","nome_completo":"Antônio Carlos Peixoto de Magalhães Neto","sq":"50002533190","situacao":"deferido","cargo_candidato":"Governador","uf_candidato":"BA","antes":"Antônio Carlos Peixoto de Magalhães Neto é advogado e político brasileiro, filiado ao União Brasil. Foi deputado federal pela Bahia (2003–2013) pelo PFL/DEM, prefeito de Salvador (2013–2020) pelo DEM e dirigente nacional do União Brasil; sem mandato eletivo atualmente. O pedido de registro da candidatura ao governo da Bahia consta na base oficial de candidaturas do TSE e aguarda julgamento; registro pendente não equivale a candidatura deferida.","depois":"Antônio Carlos Peixoto de Magalhães Neto é advogado e político brasileiro, filiado ao União Brasil. Foi deputado federal pela Bahia (2003–2013) pelo PFL/DEM, prefeito de Salvador (2013–2020) pelo DEM e dirigente nacional do União Brasil; sem mandato eletivo atualmente. O pedido de registro da candidatura ao governo da Bahia consta na base oficial de candidaturas do TSE."},{"tabela":"candidatos","id":"18d872c1-3e51-4856-9a93-2ca53b35d78f","candidato_id":"18d872c1-3e51-4856-9a93-2ca53b35d78f","slug":"alexandre-kalil","nome_completo":"Alexandre Kalil","sq":"130002539775","situacao":"deferido","cargo_candidato":"Governador","uf_candidato":"MG","antes":"Alexandre Kalil é empresário, ex-presidente do Clube Atlético Mineiro e ex-prefeito de Belo Horizonte. O pedido de registro da candidatura ao governo de Minas Gerais consta na base oficial de candidaturas do TSE e aguarda julgamento; registro pendente não equivale a candidatura deferida.","depois":"Alexandre Kalil é empresário, ex-presidente do Clube Atlético Mineiro e ex-prefeito de Belo Horizonte. O pedido de registro da candidatura ao governo de Minas Gerais consta na base oficial de candidaturas do TSE."},{"tabela":"candidatos","id":"c89aaf3b