registro pendente não equivale a candidatura deferida.","depois":"Candidatura ao governo do Ceará em 2026 pelo PSTU. O pedido de registro consta na base oficial de candidaturas do TSE."},{"tabela":"historico_politico","id":"353808cb-c4f8-40be-923a-eca05db14e85","candidato_id":"4b8485ab-cbe3-4c58-99be-3dfc05d39c5d","slug":"rico-pinheiro","nome_completo":"ALDERICO DA SILVA PINHEIRO FILHO","sq":"70002553982","situacao":"aguardando julgamento","cargo_candidato":"Governador","uf_candidato":"DF","ano":2010,"fim":2010,"tipo":"candidatura","cargo":"Deputado Estadual","estado":"AP","proveniencia":"tse","antes":"Candidatura: #NULO (TSE 2010)","depois":"Candidatura: (TSE 2010)"}]$manifesto$;
  alvos jsonb; a jsonb; r jsonb; preimagem jsonb := '[]'::jsonb;
  c public.candidatos%ROWTYPE; h public.historico_politico%ROWTYPE;
  atual text; esperado text; quantidade integer; ja_aplicado boolean;
BEGIN
  alvos := manifesto::jsonb;
  IF encode(sha256(convert_to(manifesto,'UTF8')),'hex') <> '1209862f1302a68e22890aee146f86efae9ce8f707ad84775ed18d7d1dffc8ac'
     OR jsonb_array_length(alvos) <> 188 THEN RAISE EXCEPTION 'textos julgamento: manifesto invalido'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.candidatos WHERE id IN (SELECT (x->>'candidato_id')::uuid FROM jsonb_array_elements(alvos) x)) THEN
    RAISE NOTICE 'textos julgamento: coorte ausente, replay sem escrita'; RETURN;
  END IF;
  -- Ordem única dos locks; valida o lote inteiro antes da primeira escrita.
  PERFORM 1 FROM public.candidatos WHERE id IN (SELECT (x->>'candidato_id')::uuid FROM jsonb_array_elements(alvos) x) ORDER BY id FOR UPDATE;
  PERFORM 1 FROM public.historico_politico WHERE id IN (SELECT (x->>'id')::uuid FROM jsonb_array_elements(alvos) x WHERE x->>'tabela'='historico_politico') ORDER BY id FOR UPDATE;
  SELECT count(*) INTO quantidade FROM public.coleta_log WHERE execucao='migration:20260905150000';
  IF quantidade > 1 OR EXISTS(SELECT 1 FROM public.coleta_log WHERE execucao='rollback:20260905150000') THEN
    RAISE EXCEPTION 'textos julgamento: recibo duplicado ou rollback ja executado';
  END IF;
  ja_aplicado := quantidade=1;
  IF ja_aplicado THEN
    SELECT detalhe::jsonb INTO r FROM public.coleta_log WHERE execucao='migration:20260905150000' AND volume=188 AND natureza='escrita' AND resultado='encontrado';
    IF r->>'manifesto' IS DISTINCT FROM manifesto THEN RAISE EXCEPTION 'textos julgamento: recibo invalido'; END IF;
  END IF;
  FOR a IN SELECT value FROM jsonb_array_elements(alvos) LOOP
    SELECT * INTO c FROM public.candidatos WHERE id=(a->>'candidato_id')::uuid;
    IF NOT FOUND OR c.slug IS DISTINCT FROM a->>'slug' OR c.nome_completo IS DISTINCT FROM a->>'nome_completo'
       OR c.sq_candidato_2026 IS DISTINCT FROM a->>'sq' OR c.situacao_candidatura IS DISTINCT FROM a->>'situacao'
       OR c.cargo_disputado IS DISTINCT FROM a->>'cargo_candidato' OR c.estado IS DISTINCT FROM a->>'uf_candidato'
       OR NOT EXISTS (SELECT 1 FROM public.candidatos_publico p WHERE p.id=c.id) THEN
      RAISE EXCEPTION 'textos julgamento: identidade/situacao/publicacao divergiu para %',a->>'slug';
    END IF;
    IF a->>'tabela'='candidatos' THEN
      IF a->>'id' IS DISTINCT FROM c.id::text THEN RAISE EXCEPTION 'textos julgamento: id da bio divergiu'; END IF;
      atual := c.biografia;
    ELSIF a->>'tabela'='historico_politico' THEN
      SELECT * INTO h FROM public.historico_politico WHERE id=(a->>'id')::uuid;
      IF NOT FOUND OR h.candidato_id IS DISTINCT FROM c.id OR h.periodo_inicio IS DISTINCT FROM (a->>'ano')::integer
         OR h.periodo_fim IS DISTINCT FROM (a->>'fim')::integer OR h.tipo_evento IS DISTINCT FROM a->>'tipo'
         OR h.cargo IS DISTINCT FROM a->>'cargo' OR h.estado IS DISTINCT FROM a->>'estado'
         OR h.proveniencia IS DISTINCT FROM a->>'proveniencia' OR h.despublicado_em IS NOT NULL THEN
        RAISE EXCEPTION 'textos julgamento: historico divergiu para %',a->>'id';
      END IF;
      atual := h.observacoes;
    ELSE RAISE EXCEPTION 'textos julgamento: tabela nao autorizada';
    END IF;
    esperado := CASE WHEN ja_aplicado THEN a->>'depois' ELSE a->>'antes' END;
    IF atual IS DISTINCT FROM esperado OR sha256(convert_to(atual,'UTF8')) IS DISTINCT FROM sha256(convert_to(esperado,'UTF8')) THEN
      RAISE EXCEPTION 'textos julgamento: pre/postestado divergiu para %:%',a->>'tabela',a->>'id';
    END IF;
    preimagem := preimagem || jsonb_build_array(jsonb_build_object('tabela',a->>'tabela','id',a->>'id','valor',atual));
  END LOOP;
  IF ja_aplicado THEN
    IF r->'preimagem' IS DISTINCT FROM (SELECT jsonb_agg(jsonb_build_object('tabela',x->>'tabela','id',x->>'id','valor',x->>'antes')) FROM jsonb_array_elements(alvos) x) THEN
      RAISE EXCEPTION 'textos julgamento: preimagem adulterada';
    END IF;
    RETURN;
  END IF;
  -- @write tabela=coleta_log ref=migration:20260905150000 campos=fonte,escopo,alvo,resultado,volume,detalhe,url,execucao,natureza
  INSERT INTO public.coleta_log(fonte,escopo,alvo,resultado,volume,detalhe,url,execucao,natureza)
  VALUES('textos-julgamento','global','candidatos.biografia+historico_politico.observacoes','encontrado',188,
    jsonb_build_object('manifesto',manifesto,'preimagem',preimagem)::text,
    'https://dadosabertos.tse.jus.br/dataset/candidatos-2026','migration:20260905150000','escrita');
