  UPDATE public.candidatos SET biografia='Antônio Carlos Peixoto de Magalhães Neto é advogado e político brasileiro, filiado ao União Brasil. Foi deputado federal pela Bahia (2003–2013) pelo PFL/DEM, prefeito de Salvador (2013–2020) pelo DEM e dirigente nacional do União Brasil; sem mandato eletivo atualmente. O pedido de registro da candidatura ao governo da Bahia consta na base oficial de candidaturas do TSE.' WHERE id='1d083d19-96c3-4a41-9d75-6abffacc4a3a'::uuid AND biografia='Antônio Carlos Peixoto de Magalhães Neto é advogado e político brasileiro, filiado ao União Brasil. Foi deputado federal pela Bahia (2003–2013) pelo PFL/DEM, prefeito de Salvador (2013–2020) pelo DEM e dirigente nacional do União Brasil; sem mandato eletivo atualmente. O pedido de registro da candidatura ao governo da Bahia consta na base oficial de candidaturas do TSE e aguarda julgamento; registro pendente não equivale a candidatura deferida.';
  GET DIAGNOSTICS quantidade = ROW_COUNT;
  IF quantidade<>1 THEN RAISE EXCEPTION 'textos julgamento: cardinalidade divergiu 1d083d19-96c3-4a41-9d75-6abffacc4a3a'; END IF;
