  -- @write tabela=candidatos slug=david-almeida chave=edddfd43-0528-41eb-977a-feacdbbbe8fc campos=biografia
  UPDATE public.candidatos SET biografia='David Antônio Abisai Pereira de Almeida é político brasileiro filiado ao Avante em março de 2026, segundo cobertura da imprensa (G1 AM, Metrópoles), para a disputa ao governo do Amazonas após renúncia à Prefeitura de Manaus. O TSE (base de candidaturas, Amazonas) registra a legenda em cada pleito relevante: PSL em 2004 (vereador em Manaus); PAN em 2006 (deputado estadual); PMN em 2010; PSD em 2014; PSB em 2018 (candidato a governador); Avante em 2020 e 2024 (prefeito de Manaus). As mudanças de legenda entre um pleito e outro são inferidas entre datas de eleição, sem data certa de filiação quando só há prova eleitoral. Em 2020 e 2024 o partido de candidatura é Avante; coligações municipais podem incluir outras legendas (ex.: MDB em 2024) sem equivaler a filiação do candidato — descartar troca AVANTE→MDB derivada só de composição de coligação ou ruído de agregação. Articulações ou chapas citadas na imprensa em 2026 não substituem essa sequência por pleito nem comprovam filiação intermediária ao MDB. Foi prefeito de Manaus de 1 de janeiro de 2021 a 31 de março de 2026, quando renunciou para disputar o governo do estado. O pedido de registro da candidatura ao governo do Amazonas consta na base oficial de candidaturas do TSE.' WHERE id='edddfd43-0528-41eb-977a-feacdbbbe8fc'::uuid AND biografia='David Antônio Abisai Pereira de Almeida é político brasileiro filiado ao Avante em março de 2026, segundo cobertura da imprensa (G1 AM, Metrópoles), para a disputa ao governo do Amazonas após renúncia à Prefeitura de Manaus. O TSE (base de candidaturas, Amazonas) registra a legenda em cada pleito relevante: PSL em 2004 (vereador em Manaus); PAN em 2006 (deputado estadual); PMN em 2010; PSD em 2014; PSB em 2018 (candidato a governador); Avante em 2020 e 2024 (prefeito de Manaus). As mudanças de legenda entre um pleito e outro são inferidas entre datas de eleição, sem data certa de filiação quando só há prova eleitoral. Em 2020 e 2024 o partido de candidatura é Avante; coligações municipais podem incluir outras legendas (ex.: MDB em 2024) sem equivaler a filiação do candidato — descartar troca AVANTE→MDB derivada só de composição de coligação ou ruído de agregação. Articulações ou chapas citadas na imprensa em 2026 não substituem essa sequência por pleito nem comprovam filiação intermediária ao MDB. Foi prefeito de Manaus de 1 de janeiro de 2021 a 31 de março de 2026, quando renunciou para disputar o governo do estado. O pedido de registro da candidatura ao governo do Amazonas consta na base oficial de candidaturas do TSE e aguarda julgamento; registro pendente não equivale a candidatura deferida.';
