  -- @write tabela=candidatos slug=dr-daniel chave=dcc4a93e-4114-43e9-b067-4581ed12cfd5 campos=biografia
  UPDATE public.candidatos SET biografia='Daniel Barbosa Santos, conhecido como Dr. Daniel, é médico e político brasileiro, filiado ao Podemos desde março de 2026. A trajetória partidária consolidada no TSE e na imprensa (G1, O Liberal) inclui o PSDB até 2018, filiação ao MDB em 2018 (eleição à Prefeitura de Ananindeua em 2020 pelo MDB), filiação ao PSB em 2024 e eleição à prefeitura pelo PSB no mesmo ano; em seguida filiou-se ao Podemos para disputar o governo do Pará. Registros editoriais antigos com datas ou siglas incorretas (incluindo PSD sem comprovação) foram afastados na verificação de 12/04/2026. Foi deputado estadual (2019–2023) e prefeito de Ananindeua até 2 de abril de 2026, quando renunciou ao cargo. O pedido de registro da candidatura ao governo do Pará consta na base oficial de candidaturas do TSE.' WHERE id='dcc4a93e-4114-43e9-b067-4581ed12cfd5'::uuid AND biografia='Daniel Barbosa Santos, conhecido como Dr. Daniel, é médico e político brasileiro, filiado ao Podemos desde março de 2026. A trajetória partidária consolidada no TSE e na imprensa (G1, O Liberal) inclui o PSDB até 2018, filiação ao MDB em 2018 (eleição à Prefeitura de Ananindeua em 2020 pelo MDB), filiação ao PSB em 2024 e eleição à prefeitura pelo PSB no mesmo ano; em seguida filiou-se ao Podemos para disputar o governo do Pará. Registros editoriais antigos com datas ou siglas incorretas (incluindo PSD sem comprovação) foram afastados na verificação de 12/04/2026. Foi deputado estadual (2019–2023) e prefeito de Ananindeua até 2 de abril de 2026, quando renunciou ao cargo. O pedido de registro da candidatura ao governo do Pará consta na base oficial de candidaturas do TSE e aguarda julgamento; registro pendente não equivale a candidatura deferida.';
  GET DIAGNOSTICS quantidade = ROW_COUNT;
  IF quantidade<>1 THEN RAISE EXCEPTION 'textos julgamento: cardinalidade divergiu dcc4a93e-4114-43e9-b067-4581ed12cfd5'; END IF;
