  UPDATE public.candidatos SET biografia='Antônio Paulo de Oliveira Furlan, conhecido como Dr. Furlan, é médico e político do Amapá. Foi deputado estadual, eleito em 2014 e reeleito em 2018, venceu a Prefeitura de Macapá em 2020 e foi reeleito em 2024 pelo MDB com ampla votação. Em março de 2026, já filiado ao PSD, renunciou à prefeitura após afastamento pelo STF e declarou intenção de disputar o governo do Amapá. O pedido de registro da candidatura ao governo do Amapá consta na base oficial de candidaturas do TSE.' WHERE id='9f2c557f-7c5a-459b-b0f5-faa6d561a4ce'::uuid AND biografia='Antônio Paulo de Oliveira Furlan, conhecido como Dr. Furlan, é médico e político do Amapá. Foi deputado estadual, eleito em 2014 e reeleito em 2018, venceu a Prefeitura de Macapá em 2020 e foi reeleito em 2024 pelo MDB com ampla votação. Em março de 2026, já filiado ao PSD, renunciou à prefeitura após afastamento pelo STF e declarou intenção de disputar o governo do Amapá. O pedido de registro da candidatura ao governo do Amapá consta na base oficial de candidaturas do TSE e aguarda julgamento; registro pendente não equivale a candidatura deferida.';
