  -- @write tabela=candidatos slug=omar-aziz chave=9fe469dc-058f-487d-b888-ba113f5535ae campos=biografia
  UPDATE public.candidatos SET biografia='Omar José Abdel Aziz é político brasileiro, filiado ao Partido Social Democrático (PSD) desde 2011, quando integrou a fundação da legenda no Amazonas. A trajetória partidária consolidada nas fontes oficiais inclui o PPR na candidatura a vereador em Manaus em 1996; a reorganização progressista levou ao PPB em 1997; em 2000 filiou-se ao PFL na disputa de vice-prefeito de Manaus; migrou ao PMN em 2004 e ao PSD em 2011. É senador pelo Amazonas (mandato atual 2023–2031) e foi governador do estado entre 2011 e 2015. O pedido de registro da candidatura ao governo do Amazonas consta na base oficial de candidaturas do TSE.' WHERE id='9fe469dc-058f-487d-b888-ba113f5535ae'::uuid AND biografia='Omar José Abdel Aziz é político brasileiro, filiado ao Partido Social Democrático (PSD) desde 2011, quando integrou a fundação da legenda no Amazonas. A trajetória partidária consolidada nas fontes oficiais inclui o PPR na candidatura a vereador em Manaus em 1996; a reorganização progressista levou ao PPB em 1997; em 2000 filiou-se ao PFL na disputa de vice-prefeito de Manaus; migrou ao PMN em 2004 e ao PSD em 2011. É senador pelo Amazonas (mandato atual 2023–2031) e foi governador do estado entre 2011 e 2015. O pedido de registro da candidatura ao governo do Amazonas consta na base oficial de candidaturas do TSE e aguarda julgamento; registro pendente não equivale a candidatura deferida.';
